) VALUES (
    'bormio-venue-guide',
    '{"en": "Bormio: Where Speed Meets Spectacle", "de": "Bormio: Wo Geschwindigkeit auf Spektakel trifft", "fr": "Bormio : Où la vitesse rencontre le spectacle", "it": "Bormio: Dove la velocità incontra lo spettacolo", "es": "Bormio: Donde la velocidad se encuentra con el espectáculo", "pt": "Bormio: Onde a velocidade encontra o espetáculo", "nl": "Bormio: Waar snelheid spektakel ontmoet", "ar": "بورميو: حيث تلتقي السرعة بالإثارة", "ja": "ボルミオ：スピードとスペクタクルが出会う場所", "zh": "Bormio: Sudu yu Jingcai de Xiangyu", "ko": "보르미오: 속도와 스펙터클이 만나는 곳"}'::jsonb,
    '{"en": "The Stelvio course at Bormio is one of the most demanding downhill tracks in alpine skiing. Located in the Italian Alps, it challenges the world''s bravest speed specialists.", "de": "Die Stelvio-Strecke in Bormio ist eine der anspruchsvollsten Abfahrtsstrecken im Ski Alpin.", "fr": "La piste Stelvio à Bormio est l''une des descentes les plus exigeantes du ski alpin.", "it": "La pista Stelvio a Bormio è una delle discese più impegnative dello sci alpino.", "es": "La pista Stelvio en Bormio es una de las bajadas más exigentes del esquí alpino.", "pt": "A pista Stelvio em Bormio é uma das descidas mais exigentes do esqui alpino.", "nl": "De Stelvio-afdaling in Bormio is een van de meest veeleisende afdalingen in de alpine ski.", "ar": "مسار ستيلفيو في بورميو هو واحد من أصعب مسارات الانحدار في التزلج الألبي", "ja": "ボルミオのステルヴィオコースは、アルペンスキーで最も過酷なダウンヒルトラックの一つです。", "zh": "Bormio de Stelvio saidao shi gaoshan huaxue zhong zui yanke de huajiang saidao zhiyi.", "ko": "보르미오의 스텔비오 코스는 알파인 스키에서 가장 까다로운 활강 트랙 중 하나입니다."}'::jsonb,
    '{"en": "<p>Bormio''s Stelvio course stands among the most feared and respected downhill tracks in World Cup <a href=\"/alpine-skiing-guide/\">alpine skiing</a>. This Italian venue tests courage, skill, and physical endurance in equal measure.</p><h2>The Stelvio Course</h2><p>The Stelvio is famous for its technical difficulty and sheer speed. Athletes regularly exceed 130 km/h on sections of the course, with challenging compressions, jumps, and technical turns that punish any mistake.</p><p>What makes Bormio particularly demanding is the combination of speed and technical sections. Unlike some downhill courses that favor pure gliders, the Stelvio requires complete racers who can handle everything.</p><h2>Physical Demands</h2><p>The course is brutally physical. The compressions create forces that test even the strongest legs, while the sustained speed requires exceptional cardiovascular fitness. Many athletes describe the Stelvio as one of the most exhausting races of the season.</p><p>Champions like <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> and <a href=\"/marco-schwarz-profile/\">Marco Schwarz</a> have conquered this mountain.</p><h2>Historic Moments</h2><p>Bormio has witnessed legendary performances and dramatic crashes. The course respects no reputation - even the best skiers approach it with healthy caution. Victories here are celebrated as special achievements.</p><h2>Location</h2><p>The resort sits in Lombardy, near the Stelvio Pass and the Swiss border. The town offers traditional Italian alpine charm with excellent restaurants and hotels. The spa tradition dating back to Roman times adds another dimension to the visitor experience.</p><h2>Spectator Experience</h2><p>Watching racing at Bormio provides an adrenaline rush even from the spectator areas. The speed and commitment of the athletes is palpable, and the Italian fans create a passionate atmosphere.</p><h2>Getting There</h2><p>Bormio is accessible from Milan Malpensa Airport (about 3 hours by car) or via the Stelvio Pass in summer months. Winter access typically comes from the Lombardy side.</p>", "de": "<p>Bormios Stelvio-Strecke gehört zu den gefürchtetsten und respektiertesten Abfahrtsstrecken im Weltcup-<a href=\"/alpine-skiing-guide/\">Ski Alpin</a>. Dieser italienische Austragungsort testet Mut, Können und körperliche Ausdauer gleichermaßen.</p><h2>Die Stelvio-Strecke</h2><p>Die Stelvio ist berühmt für ihre technische Schwierigkeit und pure Geschwindigkeit. Athleten überschreiten regelmäßig 130 km/h auf Abschnitten der Strecke.</p><h2>Physische Anforderungen</h2><p>Die Strecke ist brutal körperlich. Champions wie <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> haben diesen Berg bezwungen.</p><h2>Lage</h2><p>Das Resort liegt in der Lombardei, nahe dem Stilfser Joch.</p>", "fr": "<p>La piste Stelvio de Bormio figure parmi les descentes les plus redoutées et respectées de la Coupe du monde de <a href=\"/alpine-skiing-guide/\">ski alpin</a>. Ce site italien teste le courage, l''habileté et l''endurance physique.</p><h2>La piste Stelvio</h2><p>La Stelvio est célèbre pour sa difficulté technique et sa vitesse pure. Les athlètes dépassent régulièrement 130 km/h sur certaines sections.</p><h2>Exigences physiques</h2><p>Le parcours est brutalement physique. Des champions comme <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> ont conquis cette montagne.</p><h2>Emplacement</h2><p>La station est située en Lombardie, près du col du Stelvio.</p>", "it": "<p>La pista Stelvio di Bormio è tra le discese più temute e rispettate della Coppa del Mondo di <a href=\"/alpine-skiing-guide/\">sci alpino</a>. Questa sede italiana mette alla prova coraggio, abilità e resistenza fisica in egual misura.</p><h2>La pista Stelvio</h2><p>La Stelvio è famosa per la sua difficoltà tecnica e la pura velocità. Gli atleti superano regolarmente i 130 km/h in alcune sezioni.</p><h2>Richieste fisiche</h2><p>Il percorso è brutalmente fisico. Campioni come <a href=\"/vincent-kriechmayr-profile/\">Vincent Kriechmayr</a> hanno conquistato questa montagna.</p><h2>Posizione</h2><p>La località si trova in Lombardia, vicino al Passo dello Stelvio.</p>", "es": "<p>La pista Stelvio de Bormio se encuentra entre las bajadas más temidas y respetadas de la Copa del Mundo de <a href=\"/alpine-skiing-guide/\">esquí alpino</a>. Este lugar italiano pone a prueba el coraje, la habilidad y la resistencia física.</p><h2>La pista Stelvio</h2><p>La Stelvio es famosa por su dificultad técnica y velocidad pura.</p><h2>Ubicación</h2><p>El resort se encuentra en Lombardía, cerca del Paso del Stelvio.</p>", "pt": "<p>A pista Stelvio de Bormio está entre as descidas mais temidas e respeitadas da Copa do Mundo de <a href=\"/alpine-skiing-guide/\">esqui alpino</a>. Este local italiano testa coragem, habilidade e resistência física.</p><h2>A pista Stelvio</h2><p>A Stelvio é famosa por sua dificuldade técnica e velocidade pura.</p><h2>Localização</h2><p>O resort fica na Lombardia, perto do Passo dello Stelvio.</p>", "nl": "<p>De Stelvio-afdaling van Bormio behoort tot de meest gevreesde en gerespecteerde afdalingen in de Wereldbeker <a href=\"/alpine-skiing-guide/\">alpine skiën</a>. Deze Italiaanse locatie test moed, vaardigheid en fysiek uithoudingsvermogen.</p><h2>De Stelvio-piste</h2><p>De Stelvio is beroemd om zijn technische moeilijkheid en pure snelheid.</p>", "ar": "<p>يقف مسار ستيلفيو في بورميو بين أكثر مسارات الانحدار رعباً واحتراماً في كأس العالم <a href=\"/alpine-skiing-guide/\">للتزلج الألبي</a>. يختبر هذا الموقع الإيطالي الشجاعة والمهارة والتحمل البدني.</p><h2>مسار ستيلفيو</h2><p>ستيلفيو مشهور بصعوبته التقنية وسرعته الهائلة.</p>", "ja": "<p>ボルミオのステルヴィオコースは、ワールドカップ<a href=\"/alpine-skiing-guide/\">アルペンスキー</a>で最も恐れられ、尊敬されているダウンヒルトラックの一つです。このイタリアの会場は、勇気、スキル、体力を等しくテストします。</p><h2>ステルヴィオコース</h2><p>ステルヴィオは、技術的な難しさと純粋なスピードで有名です。</p>", "zh": "<p>Bormio de Stelvio saidao shi Shijie Bei <a href=\"/alpine-skiing-guide/\">gaoshan huaxue</a> zhong zui bei jusang he zunzhong de huajiang saidao zhiyi. Zhe ge Yidali changguan tongdeng de kaoya yongqi, jineng he tili.</p><h2>Stelvio saidao</h2><p>Stelvio yi qi jishu nandu he chuncui sudu erwen ming.</p>", "ko": "<p>보르미오의 스텔비오 코스는 월드컵 <a href=\"/alpine-skiing-guide/\">알파인 스키</a>에서 가장 두렵고 존경받는 활강 트랙 중 하나입니다. 이 이탈리아 경기장은 용기, 기술, 체력을 동등하게 테스트합니다.</p><h2>스텔비오 코스</h2><p>스텔비오는 기술적 난이도와 순수한 속도로 유명합니다.</p>"}'::jsonb,
    'venue-guide',
    'AS',
    '{"en": "Bormio venue guide - Home of the legendary Stelvio downhill course in the Italian Alps, one of the most demanding speed tracks in World Cup alpine skiing.", "de": "Bormio Venue Guide - Heimat der legendären Stelvio-Abfahrt in den italienischen Alpen.", "fr": "Guide du site de Bormio - Terre de la légendaire descente du Stelvio dans les Alpes italiennes.", "it": "Guida alla sede di Bormio - Casa della leggendaria pista Stelvio nelle Alpi italiane.", "es": "Guía del lugar de Bormio - Hogar de la legendaria pista Stelvio en los Alpes italianos.", "pt": "Guia do local de Bormio - Lar da lendária pista Stelvio nos Alpes italianos.", "nl": "Bormio locatiegids - Thuisbasis van de legendarische Stelvio-afdaling in de Italiaanse Alpen.", "ar": "دليل موقع بورميو - موطن مسار ستيلفيو الأسطوري للانحدار في جبال الألب الإيطالية", "ja": "ボルミオ会場ガイド - イタリアアルプスの伝説的なステルヴィオダウンヒルコースの本拠地", "zh": "Bormio changguan zhinan - Yidali Aerbisi chuanqi Stelvio huajiang saidao de suozaidi", "ko": "보르미오 경기장 가이드 - 이탈리아 알프스의 전설적인 스텔비오 활강 코스의 본거지"}'::jsonb,
    'published',
    NOW(),
    'evergreen'
) ON CONFLICT (slug) DO UPDATE SET
